function renderHero(){if(reduced)return;const h=$('.hero'),p=Math.max(0,Math.min(1,-h.getBoundingClientRect().top/(h.offsetHeight*.9)));$('.hero-title').style.transform=`translate3d(${-p*18}%,${-p*70}px,0)`;$('.hero-title').style.opacity=String(1-p);$('.portrait-wrap').style.transform=`translate3d(0,${-p*12}%,0) scale(${1-p*.1}) rotate(${-p*3}deg)`;$('.portrait-wrap').style.opacity=String(1-p*.85);$('.hero-back-name').style.transform=`translate3d(${-p*25}%,0,0) scale(${1+p*.2})`;$('.hero-back-name').style.opacity=String(1-p);$$('.hero-side-copy,.hero-bottom,.hero-greeting,.hero-coordinate').forEach(e=>{e.style.opacity=String(1-p);e.style.transform=`translateY(${-p*50}px)`})}
function renderGames(){const cards=$$('.game-card');if(innerWidth<=650||reduced){cards.forEach(c=>{c.style.transform='none';c.style.pointerEvents='';c.querySelector('button').tabIndex=0});return}const stack=$('.game-stack'),range=Math.max(1,stack.offsetHeight-innerHeight),p=Math.max(0,Math.min(1,-stack.getBoundingClientRect().top/range));const clamp=v=>Math.max(0,Math.min(1,v)),a=clamp((p-.07)/.38),b=clamp((p-.54)/.38);cards[0].style.transform=`translate3d(0,${-a*5}%,0) rotate(${-a*4}deg) scale(${1-a*.09})`;cards[1].style.transform=`translate3d(0,${120*(1-a)-b*3}%,0) rotate(${5*(1-a)+b*3}deg) scale(${1-b*.06})`;cards[2].style.transform=`translate3d(0,${120*(1-b)}%,0) rotate(${-5*(1-b)}deg)`;const index=p<.34?0:p<.81?1:2;$('#game-index').textContent=`0${index+1} / 03`;cards.forEach((c,i)=>{c.style.pointerEvents=i===index?'auto':'none';c.querySelector('button').tabIndex=i===index?0:-1})}
