if(fine&&!reduced&&hasGSAP){const cursor=$('.cursor');let px=-100,py=-100,cx=-100,cy=-100,raf=0;function cursorFrame(){raf=0;cx+=(px-cx)*.22;cy+=(py-cy)*.22;const size=cursor.classList.contains('active')?80:14;cursor.style.transform=`translate3d(${cx-size/2}px,${cy-size/2}px,0)`;if(Math.abs(px-cx)>.2||Math.abs(py-cy)>.2)raf=requestAnimationFrame(cursorFrame)}addEventListener('pointermove',e=>{px=e.clientX;py=e.clientY;if(!raf)raf=requestAnimationFrame(cursorFrame)},{passive:true});$$('.journal-photo,[data-open-world]').forEach(el=>{el.addEventListener('pointerenter',()=>cursor.classList.add('active'));el.addEventListener('pointerleave',()=>cursor.classList.remove('active'))});const moveX=gsap.quickTo('.hero-portrait','x',{duration:1,ease:'power3.out'}),moveY=gsap.quickTo('.hero-portrait','y',{duration:1,ease:'power3.out'});$('.hero-stage').addEventListener('pointermove',e=>{moveX((e.clientX/innerWidth-.5)*22);moveY((e.clientY/innerHeight-.5)*12)});$('.hero-stage').addEventListener('pointerleave',()=>{moveX(0);moveY(0)});$$('[data-magnetic]').forEach(b=>{b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();gsap.to(b,{x:(e.clientX-r.left-r.width/2)*.12,y:(e.clientY-r.top-r.height/2)*.15,duration:.35})});b.addEventListener('pointerleave',()=>gsap.to(b,{x:0,y:0,duration:.5,ease:'elastic.out(1,.5)'}))})}
